{"version":3,"file":"exec-app.jsdbx","sources":["../../src/client/exec-app.tsx","../../src/client/exec-app.css"],"sourcesContent":["import React from 'react';
import NavHeader from './components/shared/NavHeader';
import './exec-app.css';

/* ─── Alert Banner ─── */
function AlertBanner() {
  return (
    <div className="exec-alert-banner">
      <div className="exec-alert-banner__left">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
          <path d="M12 2L1 21h22L12 2z" fill="#f59e0b" />
          <path d="M12 9v4M12 17h.01" stroke="#0a0e1a" strokeWidth="2" strokeLinecap="round" />
        </svg>
        <span>Network health declining — backlog up 6.2%, 14 stores need intervention, 3 SLA breaches today.</span>
      </div>
      <div className="exec-alert-banner__right">
        <span className="exec-alert-banner__label">AUTO-GENERATED SUMMARY</span>
      </div>
    </div>
  );
}

/* ─── Page Title ─── */
function PageTitle() {
  return (
    <div className="exec-page-title">
      <div className="exec-page-title__left">
        <h1 className="exec-page-title__heading">Executive overview</h1>
        <p className="exec-page-title__subtitle">200 dark stores · 15 cities · 8,214 complaints in last 24h</p>
      </div>
      <div className="exec-page-title__right">
        <span className="exec-page-title__live">
          Updated 12s ago · <span className="exec-page-title__live-dot" /> LIVE
        </span>
        <span className="exec-page-title__warning">
          14 stores need intervention · PulseScore &lt; 60
        </span>
      </div>
    </div>
  );
}

/* ─── PulseScore Donut (SVG Arc) ─── */
function PulseScoreDonut() {
  const score = 78;
  const radius = 40;
  const strokeWidth = 8;
  const circumference = 2 * Math.PI * radius;
  const progress = (score / 100) * circumference;

  return (
    <div className="exec-kpi-card exec-kpi-card--pulse">
      <div className="exec-kpi-card__header">
        <span className="exec-kpi-card__label">Network PulseScore</span>
      </div>
      <div className="exec-kpi-card__donut">
        <svg width="100" height="100" viewBox="0 0 100 100">
          <circle
            cx="50" cy="50" r={radius}
            fill="none"
            stroke="#1e2a45"
            strokeWidth={strokeWidth}
          />
          <circle
            cx="50" cy="50" r={radius}
            fill="none"
            stroke="#00c896"
            strokeWidth={strokeWidth}
            strokeDasharray={`${progress} ${circumference}`}
            strokeLinecap="round"
            transform="rotate(-90 50 50)"
          />
          <text x="50" y="46" textAnchor="middle" className="exec-kpi-card__donut-score">78</text>
          <text x="50" y="62" textAnchor="middle" className="exec-kpi-card__donut-label">/100</text>
        </svg>
      </div>
      <div className="exec-kpi-card__footer">
        <span className="exec-kpi-card__trend exec-kpi-card__trend--positive">↗ 3% pts</span>
        <span className="exec-kpi-card__context"> vs prior 30d · headline metric</span>
      </div>
    </div>
  );
}

/* ─── KPI Card ─── */
interface KpiCardProps {
  label: string;
  value: string;
  trendDirection: 'up' | 'down';
  trendValue: string;
  trendContext: string;
  isPositive: boolean;
}

function KpiCard({ label, value, trendDirection, trendValue, trendContext, isPositive }: KpiCardProps) {
  const arrow = trendDirection === 'up' ? '↗' : '↘';
  const trendClass = isPositive ? 'exec-kpi-card__trend--positive' : 'exec-kpi-card__trend--negative';

  return (
    <div className="exec-kpi-card">
      <div className="exec-kpi-card__header">
        <span className="exec-kpi-card__label">{label}</span>
      </div>
      <div className="exec-kpi-card__value">{value}</div>
      <div className="exec-kpi-card__footer">
        <span className={`exec-kpi-card__trend ${trendClass}`}>{arrow} {trendValue}</span>
        <span className="exec-kpi-card__context"> {trendContext}</span>
      </div>
    </div>
  );
}

/* ─── KPI Row ─── */
function KpiRow() {
  return (
    <div className="exec-kpi-row">
      <PulseScoreDonut />
      <KpiCard
        label="Open complaints"
        value="8,214"
        trendDirection="up"
        trendValue="6.2%"
        trendContext="vs prior 30d"
        isPositive={false}
      />
      <KpiCard
        label="SLA compliance"
        value="91.4%"
        trendDirection="down"
        trendValue="1.8%"
        trendContext="target 95%"
        isPositive={false}
      />
      <KpiCard
        label="Avg resolution time"
        value="94m"
        trendDirection="down"
        trendValue="7%"
        trendContext="target 90m"
        isPositive={true}
      />
      <KpiCard
        label="Refund rate"
        value="4.6% of orders"
        trendDirection="up"
        trendValue="0.7%"
        trendContext="target 4.0%"
        isPositive={false}
      />
      <KpiCard
        label="Critical stores"
        value="14 of 200"
        trendDirection="up"
        trendValue="3%"
        trendContext="PulseScore < 60, no active fix"
        isPositive={false}
      />
    </div>
  );
}

/* ─── Complaint Volume Chart (SVG Area Chart) ─── */
function ComplaintChart() {
  const width = 560;
  const height = 240;
  const padding = { top: 20, right: 20, bottom: 40, left: 50 };
  const chartW = width - padding.left - padding.right;
  const chartH = height - padding.top - padding.bottom;

  const xLabels = ['02 Jul', '07 Jul', '12 Jul', '17 Jul', '22 Jul', '27 Jul'];
  const yMax = 10000;
  const yTicks = [0, 2500, 5000, 7500, 10000];

  // Complaints raised data (higher)
  const raisedData = [3200, 4800, 5600, 6200, 8100, 9400];
  // Complaints resolved data (lower)
  const resolvedData = [3000, 4200, 4900, 5100, 5800, 6200];

  const toX = (i: number) => padding.left + (i / (xLabels.length - 1)) * chartW;
  const toY = (v: number) => padding.top + chartH - (v / yMax) * chartH;

  const buildAreaPath = (data: number[]) => {
    const points = data.map((v, i) => `${toX(i)},${toY(v)}`).join(' L');
    const baseline = `${toX(data.length - 1)},${toY(0)} L${toX(0)},${toY(0)}`;
    return `M${points} L${baseline} Z`;
  };

  const buildLinePath = (data: number[]) => {
    return 'M' + data.map((v, i) => `${toX(i)},${toY(v)}`).join(' L');
  };

  return (
    <div className="exec-card exec-card--chart">
      <div className="exec-card__header">
        <div>
          <h3 className="exec-card__title">Complaint volume vs resolved — 30 days</h3>
          <p className="exec-card__subtitle">Intake is outpacing resolution since 21 Jul; backlog is accumulating.</p>
        </div>
        <span className="exec-card__badge exec-card__badge--warning">Backlog +1,140</span>
      </div>
      <svg width="100%" height={height} viewBox={`0 0 ${width} ${height}`} className="exec-chart-svg">
        {/* Grid lines */}
        {yTicks.map((tick) => (
          <g key={tick}>
            <line
              x1={padding.left} y1={toY(tick)}
              x2={width - padding.right} y2={toY(tick)}
              stroke="#1e2a45" strokeWidth="1"
            />
            <text x={padding.left - 8} y={toY(tick) + 4} textAnchor="end" className="exec-chart__axis-label">
              {tick === 0 ? '0' : `${(tick / 1000).toFixed(1)}k`}
            </text>
          </g>
        ))}
        {/* X-axis labels */}
        {xLabels.map((label, i) => (
          <text key={label} x={toX(i)} y={height - 10} textAnchor="middle" className="exec-chart__axis-label">
            {label}
          </text>
        ))}
        {/* Raised area */}
        <path d={buildAreaPath(raisedData)} fill="rgba(59, 130, 246, 0.15)" />
        <path d={buildLinePath(raisedData)} fill="none" stroke="#3b82f6" strokeWidth="2" />
        {/* Resolved area */}
        <path d={buildAreaPath(resolvedData)} fill="rgba(0, 200, 150, 0.15)" />
        <path d={buildLinePath(resolvedData)} fill="none" stroke="#00c896" strokeWidth="2" />
      </svg>
      <div className="exec-chart__legend">
        <span className="exec-chart__legend-item">
          <span className="exec-chart__legend-dot exec-chart__legend-dot--blue" /> Complaints raised
        </span>
        <span className="exec-chart__legend-item">
          <span className="exec-chart__legend-dot exec-chart__legend-dot--green" /> Complaints resolved
        </span>
      </div>
    </div>
  );
}

/* ─── Red Alerts ─── */
const ALERTS_DATA = [
  {
    id: 'ALT-40219',
    title: 'Store DS-1462 PulseScore dropped',
    description: 'Kolkata Central DS · PulseScore 31 · freezer FRZ-08 down, 41 complaints past SLA',
    time: '18m ago',
  },
  {
    id: 'ALT-40217',
    title: 'Cold chain failure',
    description: 'Mumbai Industrial Belt DS · Freezer FRZ-08 offline 3h',
    time: '52m ago',
  },
  {
    id: 'ALT-40214',
    title: 'Refund rate spike',
    description: 'Bengaluru Ring Road DS · Refunds 11.2% vs 4.6% target',
    time: '1h 20m ago',
  },
  {
    id: 'ALT-40208',
    title: 'Picker capacity shortfall',
    description: 'Kochi Airport Road DS · 6 of 14 pickers on shift',
    time: '2h ago',
  },
  {
    id: 'ALT-40203',
    title: 'Repeat missing-item claims',
    description: 'Hyderabad Old City DS · 23 claims from 9 customers',
    time: '3h 10m ago',
  },
];

function RedAlerts() {
  return (
    <div className="exec-card exec-card--alerts">
      <div className="exec-card__header">
        <div>
          <h3 className="exec-card__title">Red alerts</h3>
          <p className="exec-card__subtitle">Needs a leadership decision in the next 4 hours.</p>
        </div>
      </div>
      <div className="exec-alerts-list">
        {ALERTS_DATA.map((alert) => (
          <div className="exec-alert-item" key={alert.id}>
            <div className="exec-alert-item__dot" />
            <div className="exec-alert-item__content">
              <div className="exec-alert-item__header">
                <span className="exec-alert-item__title">{alert.title}</span>
                <span className="exec-alert-item__id">{alert.id}</span>
              </div>
              <p className="exec-alert-item__desc">{alert.description}</p>
            </div>
            <div className="exec-alert-item__right">
              <span className="exec-alert-item__time">{alert.time}</span>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M9 18l6-6-6-6" />
              </svg>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ─── City Bar Chart (CSS bars) ─── */
const CITY_DATA = [
  { city: 'Mumbai', value: 7200 },
  { city: 'Kolkata', value: 5800 },
  { city: 'Indore', value: 4900 },
  { city: 'Hyderabad', value: 4500 },
  { city: 'Nagpur', value: 3800 },
  { city: 'Surat', value: 3400 },
  { city: 'Jaipur', value: 3100 },
  { city: 'Bengaluru', value: 2800 },
  { city: 'Chandigarh', value: 2200 },
  { city: 'Delhi NCR', value: 1800 },
];

function CityChart() {
  const maxVal = 8000;
  const yTicks = [0, 2000, 4000, 6000, 8000];

  return (
    <div className="exec-card exec-card--city-chart">
      <div className="exec-card__header">
        <div>
          <h3 className="exec-card__title">City-wise complaints &amp; SLA</h3>
          <p className="exec-card__subtitle">Where to send regional ops leadership this week.</p>
        </div>
      </div>
      <div className="exec-bar-chart">
        <div className="exec-bar-chart__y-axis">
          {yTicks.slice().reverse().map((tick) => (
            <span key={tick} className="exec-bar-chart__y-label">{tick === 0 ? '0' : `${(tick / 1000).toFixed(0)}k`}</span>
          ))}
        </div>
        <div className="exec-bar-chart__bars">
          {CITY_DATA.map((item) => (
            <div className="exec-bar-chart__col" key={item.city}>
              <div className="exec-bar-chart__bar-wrapper">
                <div
                  className="exec-bar-chart__bar"
                  style={{ height: `${(item.value / maxVal) * 100}%` }}
                />
              </div>
              <span className="exec-bar-chart__x-label">{item.city}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ─── Top 5 Worst Stores ─── */
const WORST_STORES = [
  { name: 'Kolkata Central DS', id: 'DS-1462', city: 'Kolkata', sla: '61.9%', refunds: '10%', score: 31, change: 8 },
  { name: 'Mumbai Industrial Belt DS', id: 'DS-2162', city: 'Mumbai', sla: '57.3%', refunds: '9.6%', score: 31, change: 6 },
  { name: 'Bengaluru Ring Road DS', id: 'DS-1525', city: 'Bengaluru', sla: '60.6%', refunds: '9.2%', score: 32, change: 8 },
  { name: 'Kochi Airport Road DS', id: 'DS-1714', city: 'Kochi', sla: '61.4%', refunds: '10.1%', score: 32, change: 8 },
  { name: 'Hyderabad Old City DS', id: 'DS-1756', city: 'Hyderabad', sla: '64%', refunds: '9.5%', score: 32, change: 5 },
];

function TopWorstStores() {
  return (
    <div className="exec-card exec-card--worst-stores">
      <div className="exec-card__header">
        <div>
          <h3 className="exec-card__title">Top 5 worst stores</h3>
          <p className="exec-card__subtitle">Lowest PulseScore — click to open the store&#39;s dashboard.</p>
        </div>
      </div>
      <div className="exec-stores-list">
        {WORST_STORES.map((store) => (
          <div className="exec-store-item" key={store.id}>
            <div className="exec-store-item__content">
              <span className="exec-store-item__name">{store.name}</span>
              <span className="exec-store-item__info">
                {store.id} · {store.city} · SLA {store.sla} · refunds {store.refunds}
              </span>
            </div>
            <div className="exec-store-item__right">
              <span className="exec-store-item__score">{store.score}</span>
              <span className="exec-store-item__change">↗ {store.change} this week</span>
            </div>
            <svg className="exec-store-item__chevron" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M9 18l6-6-6-6" />
            </svg>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ─── Store Health Heatmap ─── */
interface HeatmapCity {
  name: string;
  cells: string[];
}

function generateCells(count: number, redChance: number, yellowChance: number): string[] {
  const cells: string[] = [];
  // Use a seeded-like approach with fixed patterns for consistency
  const patterns = [0.1, 0.85, 0.6, 0.92, 0.3, 0.72, 0.15, 0.88, 0.45, 0.95, 0.2, 0.78, 0.55, 0.11, 0.67, 0.33, 0.91, 0.42, 0.76, 0.08];
  for (let i = 0; i < count; i++) {
    const val = patterns[i % patterns.length];
    if (val < redChance) {
      cells.push('#ef4444');
    } else if (val < redChance + yellowChance) {
      cells.push('#f59e0b');
    } else {
      cells.push('#00c896');
    }
  }
  return cells;
}

const HEATMAP_LEFT: HeatmapCity[] = [
  { name: 'Bengaluru', cells: generateCells(18, 0.1, 0.25) },
  { name: 'Delhi NCR', cells: generateCells(20, 0.08, 0.2) },
  { name: 'Pune', cells: generateCells(15, 0.05, 0.2) },
  { name: 'Kolkata', cells: generateCells(16, 0.15, 0.3) },
  { name: 'Jaipur', cells: generateCells(12, 0.08, 0.25) },
  { name: 'Chandigarh', cells: generateCells(10, 0.05, 0.2) },
  { name: 'Kochi', cells: generateCells(11, 0.12, 0.25) },
  { name: 'Nagpur', cells: generateCells(9, 0.1, 0.3) },
];

const HEATMAP_RIGHT: HeatmapCity[] = [
  { name: 'Mumbai', cells: generateCells(22, 0.12, 0.25) },
  { name: 'Hyderabad', cells: generateCells(17, 0.1, 0.28) },
  { name: 'Chennai', cells: generateCells(14, 0.06, 0.2) },
  { name: 'Ahmedabad', cells: generateCells(13, 0.05, 0.15) },
  { name: 'Lucknow', cells: generateCells(11, 0.08, 0.22) },
  { name: 'Indore', cells: generateCells(10, 0.1, 0.3) },
  { name: 'Surat', cells: generateCells(9, 0.07, 0.2) },
];

function StoreHeatmap() {
  return (
    <div className="exec-card exec-card--heatmap">
      <div className="exec-card__header">
        <div>
          <h3 className="exec-card__title">Store health heatmap</h3>
          <p className="exec-card__subtitle">Each cell is one dark store, coloured by PulseScore. Click any cell to drill in.</p>
        </div>
        <div className="exec-heatmap__legend">
          <span className="exec-heatmap__legend-item">
            <span className="exec-heatmap__legend-swatch" style={{ background: '#00c896' }} /> ≥ 80
          </span>
          <span className="exec-heatmap__legend-item">
            <span className="exec-heatmap__legend-swatch" style={{ background: '#f59e0b' }} /> 60–79
          </span>
          <span className="exec-heatmap__legend-item">
            <span className="exec-heatmap__legend-swatch" style={{ background: '#ef4444' }} /> &lt; 60
          </span>
        </div>
      </div>
      <div className="exec-heatmap__grid">
        <div className="exec-heatmap__column">
          {HEATMAP_LEFT.map((city) => (
            <div className="exec-heatmap__row" key={city.name}>
              <span className="exec-heatmap__city">{city.name}</span>
              <div className="exec-heatmap__cells">
                {city.cells.map((color, i) => (
                  <div
                    key={i}
                    className="exec-heatmap__cell"
                    style={{ background: color }}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
        <div className="exec-heatmap__column">
          {HEATMAP_RIGHT.map((city) => (
            <div className="exec-heatmap__row" key={city.name}>
              <span className="exec-heatmap__city">{city.name}</span>
              <div className="exec-heatmap__cells">
                {city.cells.map((color, i) => (
                  <div
                    key={i}
                    className="exec-heatmap__cell"
                    style={{ background: color }}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ─── Main Executive Dashboard ─── */
function ExecApp() {
  return (
    <div className="exec-dashboard">
      <NavHeader />
      <AlertBanner />
      <div className="exec-dashboard__content">
        <PageTitle />
        <KpiRow />
        <div className="exec-dashboard__two-col">
          <ComplaintChart />
          <RedAlerts />
        </div>
        <div className="exec-dashboard__two-col">
          <CityChart />
          <TopWorstStores />
        </div>
        <StoreHeatmap />
      </div>
    </div>
  );
}

export default ExecApp;
","/* ─── Executive Dashboard Styles ─── */

:root {
  --cc-bg-primary: #0a0e1a;
  --cc-bg-card: #131a2e;
  --cc-border: #1e2a45;
  --cc-accent: #00c896;
  --cc-accent-glow: rgba(0, 200, 150, 0.1);
  --cc-warning: #f59e0b;
  --cc-critical: #ef4444;
  --cc-text-primary: #e2e8f0;
  --cc-text-secondary: #94a3b8;
  --cc-radius: 14px;
  --cc-spacing: 24px;
  --cc-blue: #3b82f6;
}

/* ─── Dashboard Container ─── */
.exec-dashboard {
  min-height: 100vh;
  background: var(--cc-bg-primary);
  color: var(--cc-text-primary);
  font-family: -apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI', sans-serif;
}

.exec-dashboard__content {
  padding: var(--cc-spacing);
  max-width: 1440px;
  margin: 0 auto;
}

/* ─── Alert Banner ─── */
.exec-alert-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 24px;
  background: rgba(245, 158, 11, 0.08);
  border-bottom: 1px solid rgba(245, 158, 11, 0.2);
}

.exec-alert-banner__left {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  color: var(--cc-warning);
}

.exec-alert-banner__right {
  display: flex;
  align-items: center;
}

.exec-alert-banner__label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--cc-text-secondary);
  background: rgba(255, 255, 255, 0.05);
  padding: 3px 8px;
  border-radius: 4px;
}

/* ─── Page Title ─── */
.exec-page-title {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 24px;
}

.exec-page-title__heading {
  font-size: 28px;
  font-weight: 700;
  margin: 0 0 4px 0;
  color: var(--cc-text-primary);
}

.exec-page-title__subtitle {
  font-size: 14px;
  color: var(--cc-text-secondary);
  margin: 0;
}

.exec-page-title__right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.exec-page-title__live {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--cc-text-secondary);
  background: rgba(255, 255, 255, 0.03);
  padding: 6px 12px;
  border-radius: 8px;
  border: 1px solid var(--cc-border);
}

.exec-page-title__live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--cc-accent);
  display: inline-block;
  animation: pulse-dot 2s infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.exec-page-title__warning {
  font-size: 12px;
  color: var(--cc-warning);
  background: rgba(245, 158, 11, 0.08);
  padding: 6px 12px;
  border-radius: 8px;
  border: 1px solid rgba(245, 158, 11, 0.2);
}

/* ─── KPI Row ─── */
.exec-kpi-row {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

/* ─── KPI Card ─── */
.exec-kpi-card {
  background: var(--cc-bg-card);
  border: 1px solid var(--cc-border);
  border-radius: var(--cc-radius);
  padding: 20px;
  display: flex;
  flex-direction: column;
}

.exec-kpi-card__header {
  margin-bottom: 12px;
}

.exec-kpi-card__label {
  font-size: 12px;
  font-weight: 500;
  color: var(--cc-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.exec-kpi-card__value {
  font-size: 28px;
  font-weight: 700;
  color: var(--cc-text-primary);
  margin-bottom: 12px;
  flex: 1;
  display: flex;
  align-items: center;
}

.exec-kpi-card__footer {
  font-size: 11px;
  color: var(--cc-text-secondary);
  line-height: 1.4;
}

.exec-kpi-card__trend {
  font-weight: 600;
}

.exec-kpi-card__trend--positive {
  color: var(--cc-accent);
}

.exec-kpi-card__trend--negative {
  color: var(--cc-critical);
}

.exec-kpi-card__context {
  color: var(--cc-text-secondary);
}

/* Pulse Score Donut */
.exec-kpi-card--pulse {
  align-items: center;
}

.exec-kpi-card__donut {
  margin: 4px 0 8px;
}

.exec-kpi-card__donut-score {
  font-size: 24px;
  font-weight: 700;
  fill: var(--cc-text-primary);
}

.exec-kpi-card__donut-label {
  font-size: 11px;
  fill: var(--cc-text-secondary);
}

/* ─── Two Column Layout ─── */
.exec-dashboard__two-col {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 20px;
  margin-bottom: 24px;
}

/* ─── Card Generic ─── */
.exec-card {
  background: var(--cc-bg-card);
  border: 1px solid var(--cc-border);
  border-radius: var(--cc-radius);
  padding: 24px;
}

.exec-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 20px;
}

.exec-card__title {
  font-size: 16px;
  font-weight: 600;
  color: var(--cc-text-primary);
  margin: 0 0 4px 0;
}

.exec-card__subtitle {
  font-size: 12px;
  color: var(--cc-text-secondary);
  margin: 0;
}

.exec-card__badge {
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 6px;
  flex-shrink: 0;
}

.exec-card__badge--warning {
  color: var(--cc-critical);
  background: rgba(239, 68, 68, 0.1);
  border: 1px solid rgba(239, 68, 68, 0.2);
}

/* ─── Complaint Chart ─── */
.exec-chart-svg {
  display: block;
  width: 100%;
}

.exec-chart__axis-label {
  font-size: 10px;
  fill: var(--cc-text-secondary);
}

.exec-chart__legend {
  display: flex;
  gap: 20px;
  margin-top: 12px;
}

.exec-chart__legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--cc-text-secondary);
}

.exec-chart__legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.exec-chart__legend-dot--blue {
  background: var(--cc-blue);
}

.exec-chart__legend-dot--green {
  background: var(--cc-accent);
}

/* ─── Red Alerts ─── */
.exec-alerts-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.exec-alert-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 10px;
  transition: background 0.15s ease;
  cursor: pointer;
}

.exec-alert-item:hover {
  background: rgba(255, 255, 255, 0.03);
}

.exec-alert-item__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--cc-critical);
  flex-shrink: 0;
}

.exec-alert-item__content {
  flex: 1;
  min-width: 0;
}

.exec-alert-item__header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 3px;
}

.exec-alert-item__title {
  font-size: 13px;
  font-weight: 600;
  color: var(--cc-text-primary);
}

.exec-alert-item__id {
  font-size: 11px;
  color: var(--cc-text-secondary);
}

.exec-alert-item__desc {
  font-size: 11px;
  color: var(--cc-text-secondary);
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.exec-alert-item__right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  flex-shrink: 0;
  color: var(--cc-text-secondary);
}

.exec-alert-item__time {
  font-size: 11px;
  color: var(--cc-text-secondary);
  white-space: nowrap;
}

/* ─── City Bar Chart ─── */
.exec-bar-chart {
  display: flex;
  gap: 8px;
  height: 200px;
}

.exec-bar-chart__y-axis {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 0 4px 24px 0;
}

.exec-bar-chart__y-label {
  font-size: 10px;
  color: var(--cc-text-secondary);
  text-align: right;
  width: 30px;
}

.exec-bar-chart__bars {
  display: flex;
  flex: 1;
  align-items: flex-end;
  gap: 8px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--cc-border);
}

.exec-bar-chart__col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
}

.exec-bar-chart__bar-wrapper {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.exec-bar-chart__bar {
  width: 70%;
  background: var(--cc-blue);
  border-radius: 4px 4px 0 0;
  min-height: 4px;
  transition: height 0.3s ease;
}

.exec-bar-chart__bar:hover {
  background: #60a5fa;
}

.exec-bar-chart__x-label {
  font-size: 9px;
  color: var(--cc-text-secondary);
  margin-top: 8px;
  text-align: center;
  white-space: nowrap;
}

/* ─── Top Worst Stores ─── */
.exec-stores-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.exec-store-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.exec-store-item:hover {
  background: rgba(255, 255, 255, 0.03);
}

.exec-store-item__content {
  flex: 1;
  min-width: 0;
}

.exec-store-item__name {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--cc-text-primary);
  margin-bottom: 2px;
}

.exec-store-item__info {
  font-size: 11px;
  color: var(--cc-text-secondary);
}

.exec-store-item__right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  flex-shrink: 0;
}

.exec-store-item__score {
  font-size: 22px;
  font-weight: 700;
  color: var(--cc-critical);
}

.exec-store-item__change {
  font-size: 10px;
  color: var(--cc-critical);
}

.exec-store-item__chevron {
  color: var(--cc-text-secondary);
  flex-shrink: 0;
}

/* ─── Heatmap ─── */
.exec-card--heatmap {
  margin-bottom: 24px;
}

.exec-heatmap__legend {
  display: flex;
  gap: 16px;
  align-items: center;
}

.exec-heatmap__legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--cc-text-secondary);
}

.exec-heatmap__legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 3px;
}

.exec-heatmap__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.exec-heatmap__column {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.exec-heatmap__row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.exec-heatmap__city {
  font-size: 12px;
  color: var(--cc-text-secondary);
  width: 90px;
  flex-shrink: 0;
  text-align: right;
}

.exec-heatmap__cells {
  display: flex;
  gap: 3px;
  flex-wrap: wrap;
}

.exec-heatmap__cell {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.exec-heatmap__cell:hover {
  transform: scale(1.5);
  box-shadow: 0 0 8px rgba(255, 255, 255, 0.2);
}

/* ─── Responsive ─── */
@media (max-width: 1200px) {
  .exec-kpi-row {
    grid-template-columns: repeat(3, 1fr);
  }
  .exec-dashboard__two-col {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .exec-kpi-row {
    grid-template-columns: repeat(2, 1fr);
  }
  .exec-heatmap__grid {
    grid-template-columns: 1fr;
  }
  .exec-page-title {
    flex-direction: column;
    gap: 12px;
  }
}
